/** 该定义是否为战斗 / 守备 / EGO 这类使用硬币拼点的类别 */
function 是拼点类别(类别) {
    return !!类别 && 拼点类别集.has(类别);
}
/**
 * 将技能库中的定义转换为运行时技能 (派生 硬币威力 / 硬币类型)。
 *
 * 统一走 `规范化技能定义` (枚举合法化 / 数值夹取 / 字段清理 / 补展示文本), 因此:
 * - 战斗 / 守备 / EGO 硬币必不为空 (规范化时已补默认一枚);
 * - 若定义只有 `效果` 文本、没有结构化 `硬币[].命中效果` 也没有 `effects`,
 *   用 效果解析 将其解析为技能级 `effects`; 解析失败安全跳过并 warn。
 */
export function 技能定义转技能(定义输入) {
    const 定义 = 规范化技能定义(定义输入);
    const 拼点 = 是拼点类别(定义.类别);
    const 硬币 = 定义.硬币 ?? [];
    const 有硬币命中效果 = 硬币.some(项 => (项.命中效果?.length ?? 0) > 0);
    let effects = 定义.effects ? 规范化效果列表(定义.effects) : undefined;
    if ((!effects || effects.length === 0) && !有硬币命中效果 && 拼点 && (定义.效果 ?? '').trim()) {
        const 解析 = 解析效果(定义.效果 ?? '');
        if (解析.效果.length > 0)
            effects = 解析.效果;
        else if (解析.修复.length > 0) {
            console.warn(`[技能库] 技能「${定义.名称}」的效果文本无法解析, 已跳过: ${解析.修复.join('; ')}`);
        }
    }
    return {
        名称: 定义.名称,
        罪孽: 定义.罪孽 ?? '暴怒',
        攻击类型: 定义.攻击类型 ?? '打击',
        基础威力: 定义.基础威力 ?? 0,
        硬币威力: 硬币.map(项 => 项.威力),
        硬币类型: 硬币.map(项 => 项.类型),
        硬币: 硬币.map(复制硬币),
        攻击等级修正: 定义.攻击等级修正 ?? 0,
        攻击容量: 定义.攻击容量 ?? 1,
        效果: 定义.效果 ?? '',
        描述: 定义.描述,
        类别: 定义.类别,
        时机: 定义.时机,
        条件: 定义.条件,
        每回合一次: 定义.每回合一次,
        守备类型: 定义.守备类型,
        SP消耗: 定义.SP消耗 ?? (定义.类别 === 'EGO' ? 10 : 0),
        effects,
    };
}
