/**
 * 应用具名角色的固定生命阶层 (罪人表): 覆盖 阶层 并按新阶层重算生命上限。
 * 原为满血则维持满血, 否则按新上限夹取当前生命值。
 */
export function 应用固定阶层(单位, 生命加成 = 0) {
    const 固定 = 查固定阶层(单位.名称);
    if (!固定 || 固定 === 单位.阶层)
        return;
    const 满血 = 单位.生命值 >= 单位.生命上限;
    单位.阶层 = 固定;
    单位.生命上限 = 计算生命上限(固定, 单位.等级, 生命加成);
    单位.生命值 = 满血 ? 单位.生命上限 : Math.min(单位.生命值, 单位.生命上限);
}
