        等级: 模板.等级,
        生命值: 模板.生命上限,
        生命上限: 模板.生命上限,
        护盾: 0,
        理智值: 0,
        混乱值: 0,
        混乱阈值: 模板.混乱阈值,
        攻击等级: 模板.攻击等级,
        防御等级: 模板.防御等级,
