export function 技能记录转技能(记录, 角色名 = 通用角色, 允许入库 = false) {
    const 结果 = {};
    const 条目 = Array.isArray(记录)
        ? 记录.filter(名 => typeof 名 === 'string' && 名.trim()).map(名 => [名, {}])
        : Object.entries(记录 ?? {}).map(([名, 原始]) => [名, (原始 ?? {})]);
    for (const [名称, 原始] of 条目) {
        const 库技能 = 查库技能(名称, 角色名);
        if (库技能) {
            结果[名称] = 库技能;
            continue;
        }
        const { 技能, 定义, 修复 } = 标准化技能(名称, 原始);
        // 仅「有角色档案的 NPC」允许把未知名技能规范后写入技能库 (玩家 / 无档案临时单位不写, 避免污染)
        const 已入库 = (() => {
            if (!允许入库 || !共享技能库 || !角色名)
                return false;
            try {
                共享技能库.增(角色名, 名称, 定义);
                return true;
            }
            catch (错误) {
                console.warn(`[技能库] 技能「${名称}」写入技能库失败`, 错误);
                return false;
            }
        })();
        console.warn(`[技能库] 技能「${名称}」未在技能库中找到, 已${已入库 ? '生成并写入技能库' : '用占位技能'}${修复.length > 0 ? `: ${修复.join('; ')}` : ''}`);
        结果[名称] = 技能;
    }
    return 结果;
}
/** 根据身份找一个模板, 找不到则用收尾人模板兜底 */
